# !/usr/bin/python3
# -*- coding: utf-8 -*-

"""
The preferences dialog of BoringGorilla.

"""

from PyQt4 import QtGui

from Preferences_design import Ui_GorillaPreferences


class PreferencesDialog(QtGui.QDialog):
    """Create a Preferences Dialog window.

    :param parent: the parent of this dialog window
    """

    def __init__(self, parent=None):
        super(PreferencesDialog, self).__init__(parent)
        # Load the UI as generated by Qt Designer
        self.ui = Ui_GorillaPreferences()
        self.ui.setupUi(self)


if __name__ == "__main__":
    import sys

    app = QtGui.QApplication(sys.argv)
    window = PreferencesDialog()
    app.setActiveWindow(window)
    window.show()
    sys.exit(app.exec_())
